/** Archived issues whose archive time is at or before `cutoff`, oldest first. */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(issues.archivedAt, issues.id)
    .limit(limit)
    .all();
  return rows.map((row) => toIssue(row));
}

export interface PurgeResult {
  readonly issueIds: readonly IssueId[];
  readonly commentIds: readonly string[];
  /** Megabytes the purged attachments were counted for (each rounded up). */
  readonly storageMb: number;
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Permanently deletes issues with their label links, comments and
 * attachments in one transaction. The projects' number high-water marks are
 * raised first so numbers are never reused.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeResult> {
  if (issueIds.length === 0) return { issueIds: [], commentIds: [], storageMb: 0 };
  const ids = [...issueIds];

  return getDb().transaction((tx) => {
    const rows = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .all();

    const highest = new Map<string, number>();
    for (const row of rows) {
      highest.set(
        row.projectId,
        Math.max(highest.get(row.projectId) ?? 0, row.number),
      );
    }
    for (const [projectId, number] of highest) {
      tx.update(projects)
        .set({
          lastIssueNumber: sql`max(${projects.lastIssueNumber}, ${number})`,
        })
        .where(
          and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)),
        )
        .run();
    }

    const foundIds = rows.map((row) => row.id as IssueId);

    const commentIds = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .all()
      .map((row) => row.id);

    const sizes = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all();
    const storageMb = sizes.reduce(
      (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
      0,
    );

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    return { issueIds: foundIds, commentIds, storageMb };
  });
}
