          if (expired.length === 0) break;

          const purged = await issueRepo.purgeIssues(
            orgId,
            expired.map((issue) => issue.id),
          );
          for (const issueId of purged.issueIds) {
            await searchRepo.deleteSearchDocument(orgId, "issue", issueId);
