          for (const commentId of purged.commentIds) {
            await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
          }
          if (purged.storageMb > 0) {
            await usageRepo.incrementUsage(orgId, {
              storageMbUsed: -purged.storageMb,
            });
          }
          result.processed += purged.issueIds.length;
          if (purged.issueIds.length === 0) break;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

